VALUES (NULL, NULL, 214408, 'Stranded: Alien Dawn', 'Stranded: Alien Dawn', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5jfc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1uno.jpg', 'Brave a new world in Stranded: Alien Dawn, a planet survival sim placing the fate of a small marooned group in your hands. Forge your story through compelling and immersive strategic gameplay as you make vital decisions to protect your survivors.', 'https://www.igdb.com/games/stranded-alien-dawn', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.2, 0, 10.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
