VALUES (NULL, NULL, 5716, 'Advent Rising', 'Advent Rising', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2l5x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1iie.jpg', 'Advent Rising is a story driven science fiction third person action adventure game developed by GlyphX Games. Written by author Orson Scott Card and published by Majesco Entertainment. Advent Rising started as a trilogy, but due to poor critical reception and poor sells the sequels were cancelled. There was a PSP title in the works called "Advent Shadow" that was also cancelled. Due to an epic story and fun gameplay, Advent Rising has acquired a cult following and is considered and underrated classic by fans.', 'https://www.igdb.com/games/advent-rising', '["Xbox", "PC (Microsoft Windows)"]', NULL, 7.4, 0, 10.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
