VALUES (NULL, NULL, 164290, 'Frostpunk 2', 'Frostpunk 2', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8yrc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2xsc.jpg', 'Frostpunk 2 is the sequel to the highly acclaimed, BAFTA-nominated society survival game. The age of steam has passed and now, oil leads the way as humanity’s newest salvation. However, with new threats on the horizon, the future of the city looks even grimmer than before.', 'https://www.igdb.com/games/frostpunk-2', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 8.1, 0, 10.02, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
