VALUES (NULL, NULL, 211242, 'Kona II: Brume', 'Kona II: Brume', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co52db.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1rjt.jpg', 'Northern Québec, 1970. A bizarre mist —the Brume— is disconnecting a rural mining village from its quiet reality. Step into the shoes of Detective Carl Faubert as he unfolds the mysteries haunting the region while battling for his own survival.', 'https://www.igdb.com/games/kona-ii-brume', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.8, 0, 8.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
