VALUES (NULL, NULL, 302147, 'Permafrost', 'Permafrost', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod570.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6lxj.jpg', 'Embark on a brutal journey of survival in a perpetual winter. Hunt and gather resources for building and utilize deep survival mechanics to craft your way through a harsh, unforgiving landscape. Forge alliances or dominate the remnants of humanity in this chilling open world saga.', 'https://www.igdb.com/games/permafrost--1', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 7.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
