VALUES (NULL, NULL, 325609, 'Dispatch', 'Dispatch', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob5ql.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6c8t.jpg', 'Dispatch is a superhero workplace comedy where choices matter. Manage a dysfunctional team of misfit heroes and strategize who to send to emergencies around the city, all while balancing office politics, personal relationships, and your own quest to become a hero.', 'https://www.igdb.com/games/dispatch--3', '["Xbox Series X|S", "Web browser", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, 8.6, 0, 1.07, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
