VALUES (NULL, NULL, 136993, 'Gotham Knights', 'Gotham Knights', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3s9z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1mrg.jpg', 'Introducing an original story set in DC’s Batman Universe, Gotham Knights offers a dynamic, interactive Gotham City where a rising criminal element has swept through the streets. With the Belfry as their base of operations, this new era of heroes will solve mysteries that connect the darkest chapters in the city’s history and must defeat notorious villains in epic confrontations. Players must save Gotham from a descent into chaos and reinvent themselves into their own version of the Dark Knight.', 'https://www.igdb.com/games/gotham-knights', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.7, 0, 1.0, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
