VALUES (NULL, NULL, 2811, 'Cartoon Network Universe: FusionFall', 'Cartoon Network Universe: FusionFall', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coawgx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsdaq.jpg', 'FusionFall is a free-to-play MMOG that takes all of the best Cartoon Network characters, re-imagines them in an anime-inspired style and sets them in dynamic new environments. Players create their own in-game avatars and battle alongside their favorite cartoon characters to save the world from an epic alien invasion. Players team up with friends and more than 50 characters from some of Cartoon Network’s most popular shows, including Ben 10 Alien Force, Dexter’s Laboratory, Foster’s Home for Imaginary Friends, Ed, Edd’ n Eddy, The Powerpuff Girls, Kids Next Door, Samurai Jack, and many more, to restore order to the Cartoon Network universe.', 'https://www.igdb.com/games/cartoon-network-universe-fusionfall', '["PC (Microsoft Windows)", "Mac"]', NULL, 4.7, 0, 1.02, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
