VALUES (NULL, NULL, 233585, 'Hi-Fi Rush', 'Hi-Fi Rush', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6219.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6m7h.jpg', 'As wannabe rockstar Chai, you’ll fight back against a sinister robotics enhancement conglomerate using rhythm-amplified combat where everything – from the motion in the environment to the blows of combat – is synced to the music.', 'https://www.igdb.com/games/hi-fi-rush', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.6, 0, 1.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
