VALUES (NULL, NULL, 3081, 'Evil Genius', 'Evil Genius', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co231o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars5p.jpg', 'Evil Genius focuses on building an island lair and the management of minions that are employed by the Evil Genius, allowing the player to progress through the main storyline with achieving world domination as the end goal of the game. Although not explicitly stated the use of historic regions the Eastern Block and events such as the Cuban Missile Crisis within the game suggest that it is set in the 1960s and 70s and that the game is progressing through an alternate timeline.', 'https://www.igdb.com/games/evil-genius', '["PC (Microsoft Windows)"]', NULL, 7.8, 0, 1.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
