VALUES (NULL, NULL, 1876, 'Spore', 'Spore', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ac9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8ev.jpg', 'From Single Cell to Galactic God, evolve your creature in a universe of your own creations. Play through Spore''s five evolutionary stages: Cell, Creature, Tribe, Civilization, and Space. Each stage has its own unique style, challenges, and goals.', 'https://www.igdb.com/games/spore', '["PC (Microsoft Windows)", "Mac"]', NULL, 7.7, 0, 1.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
