VALUES (NULL, NULL, 119347, 'Per Aspera', 'Per Aspera', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g12.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru8u.jpg', 'Per Aspera is a narrative-driven strategy game with the goal of overcoming the challenge of terraforming Mars. Explore the planet, gather resources, and make strategic decisions as you live the fantasy of scientifically-based interplanetary expansion. Hardship awaits.', 'https://www.igdb.com/games/per-aspera', '["PC (Microsoft Windows)"]', NULL, 8.0, 0, 1.02, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
