VALUES (NULL, NULL, 2720, 'Bully', 'Bully', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocd6z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4pi9.jpg', 'As a mischievous schoolboy, you’ll stand up to bullies, get picked on by teachers, play pranks, win or lose the girl, and ultimately learn to navigate the obstacles of the worst school around, Bullworth Academy - a corrupt and crumbling prep school with an uptight facade.', 'https://www.igdb.com/games/bully', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 8.7, 0, 1.06, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
