VALUES (NULL, NULL, 1885, 'Homefront', 'Homefront', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j9b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkso.jpg', 'Featuring a compelling single player story crafted by John Milius (Apocalypse Now, Red Dawn), Homefront immerses gamers in an interactive and cinematic FPS experience where they will assume an infantry role or take command of a wide variety of aerial and ground vehicles. In addition to the single-player experience, Homefront will deliver a robust multiplayer experience. In a land stripped of freedom, the brave will fight for their home.', 'https://www.igdb.com/games/homefront', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.1, 0, 9.91, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
