VALUES (NULL, NULL, 19408, 'Xenonauts 2', 'Xenonauts 2', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70b8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5nks.jpg', 'Wage a global war of resistance against an alien invasion. Command turn-based tactical battles, build a network of covert bases, directly control your fighter wings, and achieve strategic victory in a simulation of asymmetric warfare against a technologically superior foe.', 'https://www.igdb.com/games/xenonauts-2', '["PC (Microsoft Windows)"]', NULL, 8.4, 0, 8.52, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
