VALUES (NULL, NULL, 3171, 'The Saboteur', 'The Saboteur', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23vr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar23c3.jpg', 'Experience the ultimate open-world action/adventure as The Saboteur. Fight, climb, and race your way through a uniquely stylized version of Nazi-occupied France, and hunt down your sworn enemies who have taken everything from you. Enter the seedy underground world of a saboteur living in 1940s Paris, where the women are sexy, the missions are epic, and the revenge is satisfying.', 'https://www.igdb.com/games/the-saboteur', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.5, 0, 8.54, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
