VALUES (NULL, NULL, 7124, 'No More Heroes: Heroes'' Paradise', 'No More Heroes: Heroes'' Paradise', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xf7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mgz7sn0kvviwaquvkjxj.jpg', 'No More Heroes: Heroes'' Paradise is an enhanced port of No More Heroes, originally developed by Grasshopper Manufacture and directed by Goichi Suda.

In Japan, the port does not include PlayStation Move support or the additional Desperate Struggle bosses, among other things implemented for the overseas version.', 'https://www.igdb.com/games/no-more-heroes-heroes-paradise', '["PlayStation 3", "Xbox 360"]', NULL, 7.6, 0, 9.02, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
