VALUES (NULL, NULL, 122611, 'Terminator: Resistance', 'Terminator: Resistance', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1s30.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6cf.jpg', 'Terminator: Resistance, is a first-person shooter set during the ''Future War'' scenario that was only glimpsed at in the iconic films, ''THE TERMINATOR'' and ''T2: JUDGMENT DAY''. The machines are destined to lose, but at what cost?', 'https://www.igdb.com/games/terminator-resistance', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 6.1, 0, 9.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
