VALUES (NULL, NULL, 180225, 'Sailwind', 'Sailwind', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4804.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c6z.jpg', 'Sailing simulator featuring realistic sailing physics and a vast open-world to explore. Embark on cargo delivery missions, customize your boat, try fishing and cooking. A relaxing day sail, or an epic ocean voyage? Your sailing adventure starts here!', 'https://www.igdb.com/games/sailwind', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.6, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
