VALUES (NULL, NULL, 151169, 'Salt 2: Shores of Gold', 'Salt 2: Shores of Gold', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co992l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arftj.jpg', 'Salt 2 is a pirate-themed open world adventure focused on exploration, crafting, and survival. Play solo or with up to 5 friends, sailing the sea with your ship as a mobile base. Discover islands full of quests, towns, caves, and secrets. Level up, craft gear, hunt, fish, and customize your ship.', 'https://www.igdb.com/games/salt-2-shores-of-gold', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.03, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
