VALUES (NULL, NULL, 20908, 'Jalopy', 'Jalopy', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27on.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arj01.jpg', 'Set during the fall of the Eastern Bloc,travel through each of the socialist fraternal states while maintaining a spluttering 2-stroke car. Jalopy looks to replicate the wild yet philosophical voice of the road found in the great literary experiences such as Robert M. Pirsig''s Zen & the Art of Motorcycle.', 'https://www.igdb.com/games/jalopy', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 5.3, 0, 9.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
