VALUES (NULL, NULL, 150429, 'Tank Squad', 'Tank Squad', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97d7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhwg.jpg', 'Tank Squad is a tactical-combat action game. Take part in big tank battles during World War II. Play single-player or coop (4 players). Repair your tanks, replenish supplies, manage the crew and get back to the action!', 'https://www.igdb.com/games/tank-squad', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.01, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
