VALUES (NULL, NULL, 381376, 'Lakehopper', 'Lakehopper', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkiz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4vjz.jpg', 'Take flight in a seaplane flight simulator through a rugged world where you are responsible for the care and maintenance of your plane. Deliver cargo between far-flung communities in a flooded landscape that challenges your piloting skills! Fix your plane and keep flying!', 'https://www.igdb.com/games/lakehopper', '["Linux", "PC (Microsoft Windows)"]', NULL, NULL, 0, 0.0, '2026-11-26 02:21:07', '2026-11-26 02:21:07')
