VALUES (NULL, NULL, 602, 'Arx Fatalis', 'Arx Fatalis', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zpp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ob7.jpg', 'This critically acclaimed first-person RPG takes the player on an incredible adventure in the fantastic world of Arx. The game mixes an intelligent story with immersive and real medieval environments. Arx Fatalis allows the player to feel that all his actions have a direct consequence to all those around him.', 'https://www.igdb.com/games/arx-fatalis', '["Xbox", "PC (Microsoft Windows)"]', NULL, 7.8, 0, 10.23, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
