VALUES (NULL, NULL, 36623, 'Stormworks: Build and Rescue', 'Stormworks: Build and Rescue', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1jc4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arec8.jpg', 'Design and pilot your own sea-rescue service, in a rich and dramatic physics playground. Steer or fly your custom-designed, block based, programmable vehicles into fierce oceanic storms. Plan and execute thrilling rescues in a variety of challenging crisis scenarios.', 'https://www.igdb.com/games/stormworks-build-and-rescue', '["PC (Microsoft Windows)", "Mac"]', NULL, 7.1, 0, 8.452, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
