VALUES (NULL, NULL, 333443, 'The Last Caretaker', 'The Last Caretaker', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coasoq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6k70.jpg', 'The Last Caretaker is a thoughtful take on the survival-crafting genre, where every decision you make and every action has a consequence. Immerse yourself in a meticulously crafted world where the fate of humanity rests in your hands. Your mission is clear: recover human seeds, reactivate the Lazarus Complex, and launch the last of humanity to the stars.', 'https://www.igdb.com/games/the-last-caretaker', '["PC (Microsoft Windows)"]', NULL, 8.4, 0, 6.93, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
