VALUES (NULL, NULL, 44074, 'Evil Genius 2: World Domination', 'Evil Genius 2: World Domination', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2urs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5vt.jpg', 'A satirical spy-fi lair builder where YOU are the criminal mastermind! Construct your base, train your minions, defend your operations from the Forces of Justice, and achieve global domination!', 'https://www.igdb.com/games/evil-genius-2-world-domination', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.3, 0, 4.52999999999999936e+00, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
