VALUES (NULL, NULL, 55123, 'X4: Foundations', 'X4: Foundations', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qux.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4jf.jpg', 'X4: FOUNDATIONS, the long awaited sequel in the successful X series, brings our most sophisticated universe SIMULATION ever. Fly every ship, EXPLORE space or manage an empire; TRADE, FIGHT, BUILD and THINK carefully, while you embark on an epic journey.', 'https://www.igdb.com/games/x4-foundations', '["Linux", "PC (Microsoft Windows)"]', NULL, 7.7, 0, 1.69246153846153823e+01, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
