VALUES (NULL, NULL, 1077, 'Super Mario Galaxy', 'Super Mario Galaxy', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21ro.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57jl.jpg', 'A 3D platformer and first Wii entry in the Super Mario franchise, Super Mario Galaxy sees Mario jump across planets and galaxies with varying items, enemies, geographies and gravity mechanics in order to reach his enemy Bowser, who has attacked the Mushroom Kingdom and hijacked Princess Peach''s castle with her inside.', 'https://www.igdb.com/games/super-mario-galaxy', '["Wii", "Wii U"]', NULL, 9.4, 0, 6.52, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
