VALUES (NULL, NULL, 11737, 'Outer Wilds', 'Outer Wilds', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65ac.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nua.jpg', 'Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop. The newest member of the space program in a small village on the planet Timber Hearth, the player navigates a space shuttle and travels across their solar system to get to the bottom of its mysteries by exploring the cosmos and gathering the knowledge hidden within each of the system''s planets, left behind by another civilization in the distant past.', 'https://www.igdb.com/games/outer-wilds', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.7, 0, 12.305, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
