VALUES (NULL, NULL, 69547, 'Vintage Story', 'Vintage Story', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j6g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4e7f.jpg', 'Vintage Story is an uncompromising wilderness survival sandbox game that finds a fine line between hardcore survival and a cozy sandbox. Players will awaken to a ruined medieval world reclaimed by nature and permeated by eldritch, temporal disturbances as they gather resources to prepare for a harsh, approaching winter.', 'https://www.igdb.com/games/vintage-story', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 9.1, 0, 6.293333333333333e+00, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
