VALUES (NULL, NULL, 24863, 'Wasteland 3', 'Wasteland 3', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2620.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5z0.jpg', 'As the sole survivor of Team November, a Ranger squad dispatched to the icy Colorado wastes, you find this is a land of buried secrets, lost technology, fearsome lunatics, and deadly factions. No one here has ever heard of the Desert Rangers. Your reputation is yours to build from scratch, and your choices may save this land or doom it. With a renewed focus on macro-reactivity, you''ll be picking between warring factions, deciding whether locations are destroyed or saved, and making other far reaching decisions that have a marked impact on the shape of your world.', 'https://www.igdb.com/games/wasteland-3', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 8.4, 0, 8.5266666666666655e+00, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
