VALUES (NULL, NULL, 139078, 'Dyson Sphere Program', 'Dyson Sphere Program', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coar0s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvcw.jpg', 'As an engineer of Dyson Sphere Program, you will go to an alien galaxy building “Dyson Sphere”. Collecting resources, plan and designing production lines, gradually create a full automated factory. Develop your factory from a small workshop to a huge cross-galaxy Industrial empire.', 'https://www.igdb.com/games/dyson-sphere-program', '["PC (Microsoft Windows)"]', NULL, 8.0, 0, 2.02, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
