VALUES (NULL, NULL, 19333, 'Absolver', 'Absolver', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45wq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arewe.jpg', 'Absolver is an online multiplayer combat RPG where players are placed behind the mask of a Prospect under control of the Guides, the new rulers of the fallen Adal Empire, who have placed you here to determine your worth in joining their elite corps of Absolvers.', 'https://www.igdb.com/games/absolver', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 6.8, 0, 2.01, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
