VALUES (NULL, NULL, 103246, 'Space Haven', 'Space Haven', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xhv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfet.jpg', 'Embark on a space journey with your patched-together crew of civilians in search of a new home. Build spaceships tile by tile, create optimal gas conditions, manage the needs and moods of their crew, encounter other space-faring groups, and explore the universe in this spaceship colony sim.', 'https://www.igdb.com/games/space-haven', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.9, 0, 6.05, '2026-11-19 20:56:22', '2026-11-26 02:21:07')
