VALUES (NULL, NULL, 287871, 'The Forever Winter', 'The Forever Winter', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7siq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2smw.jpg', 'The Forever Winter is a co-op tactical survival horror shooter where you and your squad must loot the dead to survive under the shadow of terrifying and gargantuan war machines locked in a never-ending conflict.', 'https://www.igdb.com/games/the-forever-winter', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.54666666666666685e+00, '2026-11-20 22:18:41', '2026-11-26 02:21:07')
