VALUES (NULL, NULL, 990, 'Halo: Reach', 'Halo: Reach', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xha.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar852.jpg', 'Halo: Reach is a first-person shooter set in 2552, serving as a prequel to Halo: Combat Evolved. Players control Noble Six, a member of Noble Team, an elite squad of Spartan supersoldiers defending the human colony world of Reach from a Covenant invasion. The game features campaign gameplay playable solo or cooperatively, with armor abilities replacing single-use equipment from previous entries. Multiplayer includes competitive modes, a Firefight survival mode, and Forge World, a large-scale level editor. The game also introduces space combat dogfight sequences to the series.', 'https://www.igdb.com/games/halo-reach', '["PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 8.7, 0, 10.395, '2026-11-21 13:07:40', '2026-11-26 02:21:07')
