VALUES (NULL, NULL, 4786, 'The Evil Within', 'The Evil Within', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wgs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar69g.jpg', 'The Evil Within embodies the meaning of pure survival horror. Highly-crafted environments, horrifying anxiety, and an intricate story are combined to create an immersive world that will bring you to the height of tension. With limited resources at your disposal, you’ll fight for survival and experience profound fear in this perfect blend of horror and action.', 'https://www.igdb.com/games/the-evil-within', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.5, 0, 5.73, '2026-11-21 21:29:28', '2026-11-26 02:21:07')
