VALUES (NULL, NULL, 250, 'The Chronicles of Riddick: Escape from Butcher Bay', 'The Chronicles of Riddick: Escape from Butcher Bay', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mp7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ayygomz3iq4c3wxkmvsy.jpg', 'Escape from Butcher Bay is set in the futuristic science fiction universe of the Chronicles of Riddick franchise, and is a prequel to the film Pitch Black. The game takes place inside Butcher Bay, a maximum-security prison from which no prisoner has escaped. The facility - constructed on a barren planet - contains three increasingly secure holding areas, and a subterranean mining operation.', 'https://www.igdb.com/games/the-chronicles-of-riddick-escape-from-butcher-bay', '["Xbox", "PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 8.7, 0, 6.52, '2026-11-21 21:29:28', '2026-11-26 02:21:07')
