VALUES (NULL, NULL, 6030, 'The Warriors', 'The Warriors', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yzp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cot.jpg', 'Based on the 1979 movie of the same name. A battle on the New York streets. The armies of the night number 60,000 strong, and tonight they''re all after The Warriors - a street gang wrongly accused of killing a rival gang leader.', 'https://www.igdb.com/games/the-warriors', '["Xbox", "PlayStation 3", "PlayStation 4", "PlayStation Portable", "PlayStation 2"]', NULL, 8.2, 0, 2.045, '2026-11-21 21:29:28', '2026-11-26 02:21:07')
