VALUES (NULL, NULL, 56, 'The Elder Scrolls III: Morrowind', 'The Elder Scrolls III: Morrowind', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2knd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7ja.jpg', 'The Elder Scrolls III: Morrowind is an open-world first-person role-playing game and the third main entry in The Elder Scrolls series. Set on the island of Vvardenfell in the province of Morrowind, the player arrives as a released prisoner and becomes involved in the political and religious conflicts of the Dunmer people. Gameplay combines freeform exploration, real-time combat, and character customization across a vast landscape of ashlands, swamps, and volcanic terrain, with a main quest centered on an ancient prophecy.', 'https://www.igdb.com/games/the-elder-scrolls-iii-morrowind', '["Xbox", "PC (Microsoft Windows)"]', NULL, 7.4, 0, 8.8600000000000012e+00, '2026-11-21 21:29:28', '2026-11-26 02:21:07')
