VALUES (NULL, NULL, 134813, 'Icarus', 'Icarus', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vsi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arv36.jpg', 'An alien world for the taking. Explore, survive and make your fortune if you dare. Icarus is a multiplayer co-operative survival game with persistent metagame progression.', 'https://www.igdb.com/games/icarus--1', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 8.81666666666666643e+00, '2026-11-21 21:29:28', '2026-11-26 02:21:07')
