VALUES (NULL, NULL, 1278, 'Resistance: Fall of Man', 'Resistance: Fall of Man', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2b4m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jqowvtfozwqjlofnpfxu.jpg', 'In an alternate 1951, Sgt. Nathan Hale is among a unit of US soldiers sent to aid the British military against the invading aliens, known as Chimera. When Hale''s unit is completely wiped out in a surprise attack, he struggles for survival...', 'https://www.igdb.com/games/resistance-fall-of-man', '["PlayStation 3"]', NULL, 7.9, 0, 6.02999999999999936e+00, '2026-11-21 21:29:28', '2026-11-26 02:21:07')
