VALUES (NULL, NULL, 75235, 'Ghost of Tsushima', 'Ghost of Tsushima', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2crj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4u6z.jpg', 'Uncover the hidden wonders of Tsushima in this open-world action adventure. Forge a new path and wage an unconventional war for the freedom of Tsushima. Challenge opponents with your katana, master the bow to eliminate distant threats, develop stealth tactics to ambush enemies in order to win over the mongols.', 'https://www.igdb.com/games/ghost-of-tsushima', '["PlayStation 4", "PlayStation 5"]', NULL, 9.0, 0, 9.07333333333333413e+00, '2026-11-22 03:06:26', '2026-11-26 02:21:07')
