VALUES (NULL, NULL, 55322, 'Pathologic 2', 'Pathologic 2', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ndy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru5r.jpg', 'Pathologic 2 is a reimagining of the original, focused on the Haruspex, Artemy Burakh. You return to your plague-stricken hometown as a surgeon-healer caught between local kinship traditions, colonial urban power, impossible medicine, hunger, exhaustion, and a clock that never stops. Compared with the 2005 game, it is more mechanically coherent and cinematic, but still intentionally punishing: you are meant to triage, fail, compromise, and live with irreversible consequences.', 'https://www.igdb.com/games/pathologic-2', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.4, 0, 1.0543333333333333e+01, '2026-11-23 03:29:46', '2026-11-26 02:21:07')
