VALUES (NULL, NULL, 825, 'Saints Row', 'Saints Row', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2w7c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar79k.jpg', 'Saints Row takes place in the fictional city of Stilwater, where the main character is involved in a conflict between four rival gangs. Despite the protagonist''s attempts to remain uninvolved, you are drawn into the conflict and become a member of the Third Street Saints. As the game progresses, you go to war with Los Carnales, the Westside Rollers, and the Vice Kings, gaining status within the gang and taking over the city in the process.', 'https://www.igdb.com/games/saints-row', '["Xbox 360"]', NULL, 7.5, 0, 2.055, '2026-11-24 04:24:23', '2026-11-26 02:21:07')
